from pathlib import Path
import numpy as np,json,hashlib
root=Path('mechanism-plates-qa');d=root/'bevel-trial/100';p=np.fromfile(d/'position.bin','f4').reshape(-1,3).astype('f8');n=np.fromfile(d/'normal.bin','f4').reshape(-1,3).astype('f8');f=np.fromfile(d/'index.bin','u4').reshape(-1,3);q=p[f];cross=np.cross(q[:,1]-q[:,0],q[:,2]-q[:,0]);area=np.linalg.norm(cross,axis=1);r=json.load(open(root/'bevel-trial-report.json'))[0];pair=r['analyticBores'][0];center=np.array(pair['center']);rad=np.linalg.norm(p[:,[0,2]]-center,axis=1);y0,y1=pair['depths'];width=pair['bevelWidth'];bo=(np.abs(rad-pair['radius'])<1e-5)&(p[:,1]>=y0+width-1e-6)&(p[:,1]<=y1-width+1e-6)
# Vertex manifold test including welded exact seam labels and consistent edge orientations.
_,inv=np.unique(np.round(p,5),axis=0,return_inverse=True);ff=inv[f];directed=np.concatenate([ff[:,[0,1]],ff[:,[1,2]],ff[:,[2,0]]]);edges=np.sort(directed,1);_,ev,counts=np.unique(edges,axis=0,return_inverse=True,return_counts=True);orient=np.bincount(ev,weights=np.where(directed[:,0]<directed[:,1],1,-1));
# Cap outline and unchanged body extent exact versus original. Relief only at original bore junction.
base=np.fromfile('mechanism-planar-study/100/position.bin','f4').reshape(-1,3).astype('f8');bf=np.fromfile('mechanism-planar-study/100/original-index.bin','u4').reshape(-1,3)
report={'sourceIndex':100,'scope':'One .9-radius inner bore only, both rims; three analytic quarter-round segments per rim; other eligible cylinders use recovered analytic Delaunay candidate','releaseStatus':'isolated trial, not production and not visually accepted','trianglesLive':len(bf),'trianglesPriorCandidate':len(np.fromfile(root/'delaunay/100/index.bin','u4'))//3,'trianglesTrial':len(f),'trianglesAddedVersusLive':len(f)-len(bf),'trianglesAddedVersusPriorCandidate':len(f)-len(np.fromfile(root/'delaunay/100/index.bin','u4'))//3,'boundaryEdges':int((counts==1).sum()),'nonmanifoldEdges':int((counts>2).sum()),'orientationConflicts':int((orient!=0).sum()),'degenerateTrianglesArea2Below1e-10':int((area<1e-10).sum()),'minTriangleArea2':float(area.min()),'flippedVersusVertexNormals':int((np.einsum('ij,ij->i',cross,n[f].mean(1))<=0).sum()),'maxNormalLengthError':float(np.abs(np.linalg.norm(n,axis=1)-1).max()),'bevelWidthSourceUnits':width,'radius':pair['radius'],'sampledMinimumMidwallVertexRadius':float(rad[bo].min()),'minimumPolygonalWallRadius':float(pair['radius']*np.cos(np.pi/pair['after'])),'cylinderChordError':pair['chordError'],'clearanceCaution':'Same polygonal midwall radius as prior analytic candidate, not exact CAD clearance; no device/mechanical certification. Relief removes material only at this bore, retaining axial bounds.','boundsWithinFloat32CapRounding':bool(np.allclose(p.min(0),base.min(0),rtol=0,atol=1e-7) and np.allclose(p.max(0),base.max(0),rtol=0,atol=1e-7)), 'maxBoundsDelta':float(max(np.abs(p.min(0)-base.min(0)).max(),np.abs(p.max(0)-base.max(0)).max())),'sha256':{x:hashlib.sha256((d/x).read_bytes()).hexdigest() for x in ['position.bin','normal.bin','index.bin']}}
